class NotSupportedArgumentTypeError(NotImplementedError):
    """
    Raised when an unsupported variant of 'switch' type argument is used.
    """

    def __init__(self, variant, arg_name):
        """
        Initialize instance with super call to parent's __init__ method, using
        custom exception message as an argument.
        """
        msg_template = (
            "Variant '{0}' of argument '{1}' is unsupported. "
            "Please check documentation for a list of supported variants."
        )

        super(NotSupportedArgumentTypeError, self).__init__(msg_template.format(variant, arg_name))


class UeMobility(object):

    T3410 = 15  # 3GPP TS 24.301
    __expected_ue_registration_message = r'Received REGISTRATION COMPLETE from UE'

    def __init__(self):
        self._ute_wtssim_instance = BuiltIn().get_library_instance('ute_wtssim')
        self._ue_measurements_instance = ta5g_ue_measurements()
        self.ta5g_throughput = ta5g_throughput()

    def get_expected_ue_registration_message(self):
        return self.__expected_ue_registration_message

    def exit_idle_mode(self, ue_id, pass_regexp=None, timeout=5):
        """
        Executes egate command for given ue_id ue exits idle mode

        :param ue_id:
        :param pass_regexp:
        :param timeout:
        """
        if not pass_regexp:
            pass_regexp = 'UE{}: [=]+ UE IS ACTIVE'.format(ue_id)
        return self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_im_exit id={}'.format(ue_id), pass_regexp=pass_regexp, timeout=timeout
        )

    def exit_idle_mode_without_confirmation(self, ue_id, timeout=5):
        """
        Executes egate command for given ue_id ue exits idle mode

        :param ue_id:
        :param timeout:
        """
        self._ute_wtssim_instance.execute_egate_command(cmd='ue_im_exit id={}'.format(ue_id), timeout=timeout)

    def release_ue_ctx(self, ue_id, pass_regexp=None, timeout=5):
        """
        Executes egate command for given ue_id ue context is released

        :param ue_id:
        :param pass_regexp:
        :param timeout:
        """
        if not pass_regexp:
            pass_regexp = 'UE{}: IS IDLE'.format(ue_id)
        logger.console("UE {} context release - idle mode entry".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_ng_ctx_release id={} cause=NAS_normal_release'.format(ue_id),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

    def turn_on_off_inclusion_of_ue_capabilities(self, turn_on_off='on', ue_id='all', timeout=5):
        """
        Include UE Capability IE in NGAP Initial Context Setup Request for decicatged AMF Identifier

        :param ue_id:
        :param turn_on_off:
        :param timeout:
        """
        logger.console(
            "Inclusion of UE Capability IE in NGAP Initial Context Setup Request turned {}".format(turn_on_off)
        )
        self._ute_wtssim_instance.execute_egate_command(
            cmd='amf_ics_param id=1 ue={} include_ue_capabilities={}'.format(ue_id, turn_on_off),
            timeout=timeout,
        )

    def configure_rule_for_securitymodecommand_messages(self, ue_id, rule=None, hex=None, timeout=5):
        """
        Configures rules to specify action based on presence of certain RRC IEs in RRC SecurityModeCommand messages

        :param ue_id:
        :param rule:
        :param hex:
        :param timeout:
        """
        logger.console(
            "Configuration of {} action for RRC SecurityModeCommand messages for UE id {}".format(rule, ue_id)
        )
        cmd = 'ue_rrc_sec_mode_param id={} if_contains=any action={}'.format(ue_id, rule)
        if hex is not None:
            cmd += ' hex={}'.format(hex)
        self._ute_wtssim_instance.execute_egate_command(cmd=cmd, timeout=timeout)

    def deregister_ue_without_confirmation(self, ue_id, timeout=5):
        """
        Executes deregistration egate command for given ue_id indicating ue switch off

        :param ue_id:
        :param timeout:
        """
        logger.console("UE id {} deregistration".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_deregister id={} ue_deregister_type=switch_off'.format(ue_id),
            timeout=timeout,
        )

    def exit_idle_mode_by_mme_without_confirmation(self, ue_id):
        """
        Executes egate command for given ue_id ue exits idle mode by mme request
        No validation if process succeeds

        :param ue_id:
        """
        self._ute_wtssim_instance.execute_egate_command(cmd='ue_im_exit id={} by=mme'.format(ue_id))

    def change_ue_location(self, ue_id, dst_enb, dst_cell):
        """
        :param ue_id:
        :param dst_enb:
        :param dst_cell:
        """
        logger.console("Changing UE {} location to enb {}, cell {}".format(ue_id, dst_enb, dst_cell))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_change_location id={} enb={} cell={}'.format(ue_id, dst_enb, dst_cell),
            pass_regexp='eNB-{} cell {}'.format(dst_enb, dst_cell),
            timeout=5,
        )

    def change_multiple_ue_location(self, first_ue_id, last_ue_id, dst_enb, dst_cell):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param dst_enb:
        :param dst_cell:
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.change_ue_location(ue_id, dst_enb, dst_cell)

    def change_multiple_ues_location_without_confirmation(self, first_ue_id, last_ue_id, dst_enb, dst_cell):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param dst_enb:
        :param dst_cell:
        """
        logger.console(
            "Changing UE {}-{} location to enb {}, cell {}".format(first_ue_id, last_ue_id, dst_enb, dst_cell)
        )
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_change_location id={}-{} enb={} cell={}'.format(first_ue_id, last_ue_id, dst_enb, dst_cell)
        )

    def change_ue_location_without_confirmation(self, ue_id, dst_enb, dst_cell):
        """
        :param ue_id:
        :param dst_enb:
        :param dst_cell:
        """
        logger.console("Changing UE {} location to enb {}, cell {}".format(ue_id, dst_enb, dst_cell))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_change_location id={} enb={} cell={}'.format(ue_id, dst_enb, dst_cell)
        )

    def perform_tracking_area_update(self, ue_id):
        """
        :param ue_id:
        """
        self._ute_wtssim_instance.execute_egate_command(
            cmd='tau id={}'.format(ue_id),
            pass_regexp=r'UE{}: NAS:TAU \(TA_UPDATING\) procedure completed'.format(ue_id),
        )

    def change_ues_location_to_default(self, dst_enb=1, dst_cell=1):
        """
        :param dst_enb:
        :param dst_cell:
        """
        total_ues_number = self.get_total_number_of_configured_ues()
        self.change_multiple_ues_location_without_confirmation(1, total_ues_number, dst_enb, dst_cell)

    def verify_ue_state(self, ue_id, expected_state):
        """
        :param ue_id:
        :param expected_state: Expected state of the ue, eg. active, off, idle. Case insensitive.
        :return:
        """
        ue_state = self._get_ue_state(ue_id)
        expected_state = expected_state.lower()
        if expected_state == ue_state:
            return True
        else:
            raise ExecutionFailed(message="State '{}' is different than expected '{}'".format(ue_state, expected_state),
                                  continue_on_failure=True)

    def get_total_number_of_configured_ues(self):
        """
        :return: number of configured UEs
        """
        ue_summary_table = self._get_ue_summary_table(pass_regexp='Configured')
        p = re.compile(r'Configured *\d* *\d* *(\d*)')
        return p.findall(ue_summary_table)[0]

    def get_ids_of_configured_ues(self):
        """
        Method uses ue_summary from _get_ue_summary_table to check if UEs are configured than based on ue_disp table
        form get_ue_disp_table provides ids of configured UEs

        :return: ids of configured UEs
        """
        ue_summary_table = self._get_ue_summary_table(pass_regexp='Configured')
        ue_disp_table = self.get_ue_disp_table(pass_regexp='EGATE>')
        if 1 < int(re.findall(r'Configured *\d* *\d* *(\d*)', ue_summary_table)[0]):
            return re.findall(r'(\d+)\s+INT', ue_disp_table)
        return re.findall(r'UE-(\d+)', ue_disp_table)

    def get_total_number_of_active_ues(self):
        """
        :return: number of active UEs
        """
        ue_summary_table = self._get_ue_summary_table(pass_regexp='Active')
        p = re.compile(r'Active *\d* *\d* *(\d*)')
        return p.findall(ue_summary_table)[0]

    def check_if_ues_are_active(self, expected_ues):
        """
        Counts active ues and compares to expected number
        :param expected_ues:
        :return:
        """
        active_ues = self.get_total_number_of_active_ues()
        if int(expected_ues) == int(active_ues):
            return True
        else:
            raise ExecutionFailed(message="Active UE's number '{}' is different than expected '{}'"
                                          "".format(active_ues, expected_ues),
                                  continue_on_failure=True)

    def get_total_number_of_idle_ues(self):
        """
        :return: number of idle UEs
        """
        ue_summary_table = self._get_ue_summary_table(pass_regexp='Idle')
        p = re.compile(r'Idle *\d* *\d* *(\d*)')
        return p.findall(ue_summary_table)[0]

    def attach_ue(
        self,
        ue_id,
        optional_parameters='',
        cell=None,
        enb='1',
        establishment_cause=None,
        establishment_cause_nb=None,
        timeout=T3410,
        pass_regexp=None,
        prb_check=False
    ):
        """
        Executes egate command ue_register with optional parameters

        :param ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param establishment_cause:
        :param establishment_cause_nb:
        :param timeout:
        :param pass_regexp:
        """
        if not pass_regexp:
            pass_regexp = self.__expected_ue_registration_message
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        if establishment_cause:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause={}'.format(ue_id, establishment_cause)
            )
        if establishment_cause_nb:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause_nb={}'.format(ue_id, establishment_cause_nb)
            )
        logger.console("Attaching UE {}".format(ue_id))
        if not prb_check:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_register id={} {}'.format(ue_id, optional_parameters), pass_regexp=pass_regexp, timeout=timeout)
        else:
            self._specify_prbs_values(ue_id, optional_parameters, timeout, pass_regexp)

    def _specify_prbs_values(self, ue_id, optional_parameters, timeout, pass_regexp):
        tshark_instance = ta5g_tshark()
        output_dir = BuiltIn().get_variable_value('${OUTPUT_DIR}')
        test_dir = BuiltIn().get_variable_value('${TEST_NAME}')
        output = '{}/{}'.format(output_dir, test_dir)
        tshark_instance.start_pcaps_collection_for_test_subcase(output_dirpath=output,
                                                                subcase_name='Attach_UE_{}'.format(ue_id))
        time.sleep(1)
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} {}'.format(ue_id, optional_parameters), pass_regexp=pass_regexp, timeout=timeout)
        CSI_ResourceList_id = self.get_CSI_ResourceList_id(packet_filter='((nr-rrc.rrcSetup_element) && nr-rrc.startingPRB)',
                                                           alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        schedulingRequestResource_id = self.get_schedulingRequestResource_id(packet_filter='((nr-rrc.rrcSetup_element) && nr-rrc.startingPRB)',
                                                                             alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        startingPRB_ue_list_value = self.get_PRB_values(
            packet_filter='((nr-rrc.rrcSetup_element) && nr-rrc.startingPRB)', prb='startingPRB',
            alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        secondHopPRB_ue_list_value = self.get_PRB_values(
            packet_filter='((nr-rrc.rrcSetup_element) && nr-rrc.startingPRB)', prb='secondHopPRB',
            alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        pucch_ResourceIds_list = self.get_pucch_ResourceIds(packet_filter='(nr-rrc.rrcSetup_element) && nr-rrc.startingPRB',
                                                            alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        nrofPRBs = self.get_nrofPRBs(packet_filter='(nr-rrc.rrcSetup_element) && nr-rrc.startingPRB',
                                     alias='default_uu_subcase', subcase='Attach_UE_{}'.format(ue_id))
        tshark_instance.stop_pcaps_collection_for_test_subcase()
        global startingPRB_dict
        global secondHopPRB_dict
        CSI_startingPRB = []
        CSI_secondHopPRB = []
        SR_startingPRB = []
        SR_secondHopPRB = []
        startingPRB_values = {}
        secondHopPRB_values = {}
        CSI_startingPRB = self.extract_value_of_CSI_prb(startingPRB_ue_list_value, pucch_ResourceIds_list, CSI_ResourceList_id)
        CSI_secondHopPRB = self.extract_value_of_CSI_prb(secondHopPRB_ue_list_value, pucch_ResourceIds_list, CSI_ResourceList_id)
        SR_startingPRB = self.extract_value_of_SR_prb(startingPRB_ue_list_value, pucch_ResourceIds_list, schedulingRequestResource_id)
        SR_secondHopPRB = self.extract_value_of_SR_prb(secondHopPRB_ue_list_value, pucch_ResourceIds_list, schedulingRequestResource_id)
        startingPRB_values['startingPRB_ue_list_value'] = startingPRB_ue_list_value
        startingPRB_values['CSI_startingPRB'] = CSI_startingPRB
        startingPRB_values['SR_startingPRB'] = SR_startingPRB
        startingPRB_values['nrofPRBs'] = nrofPRBs[0]
        secondHopPRB_values['secondHopPRB_ue_list_value'] = secondHopPRB_ue_list_value
        secondHopPRB_values['CSI_secondHopPRB'] = CSI_secondHopPRB
        secondHopPRB_values['SR_secondHopPRB'] = SR_secondHopPRB
        startingPRB_dict[ue_id] = startingPRB_values
        secondHopPRB_dict[ue_id] = secondHopPRB_values
        self._write_prb_values_to_file()

    def get_startingPRB_values(self, ue_id):
        return startingPRB_dict[ue_id]['startingPRB_ue_list_value']

    def get_secondHopPRB_values(self, ue_id):
        return secondHopPRB_dict[ue_id]['secondHopPRB_ue_list_value']

    def get_value_of_CSI_startingPRB(self, ue_id):
        return startingPRB_dict[ue_id]['CSI_startingPRB']

    def get_value_of_CSI_secondHopPRB(self, ue_id):
        return secondHopPRB_dict[ue_id]['CSI_secondHopPRB']

    def get_value_of_SR_startingPRB(self, ue_id):
        return startingPRB_dict[ue_id]['SR_startingPRB']

    def get_value_of_SR_secondHopPRB(self, ue_id):
        return secondHopPRB_dict[ue_id]['SR_secondHopPRB']

    def get_value_of_nrofPRBs(self, ue_id):
        return startingPRB_dict[ue_id]['nrofPRBs']

    def get_attribute_value_from_rrc_iterface(self, element_xpath, packet_filter, alias=None, subcase=None):
        tshark_instance = ta5g_tshark()
        output_dir = BuiltIn().get_variable_value('${OUTPUT_DIR}')
        test_dir = BuiltIn().get_variable_value('${TEST_NAME}')
        try:
            pcap_file_directory = '{}/{}/tshark/'.format(output_dir, test_dir)
            pcap_pattern = '{}_UU_*.pcap'
            pcap_file_path = glob.glob(pcap_file_directory + pcap_pattern)
            attribute_value = tshark_instance.get_attribute_values_from_tshark_messages(
                alias=alias,
                filter=packet_filter,
                output_pdml_filepath="{}/converted_pcap.pdml".format(output_dir),
                element_xpath=element_xpath,
                attribute_xpath=".",
                attribute="show",
                pcap_file_path=pcap_file_path
            )
            if attribute_value:
                return attribute_value
            else:
                raise Exception
        except Exception:
            pass
        try:
            attribute_value = tshark_instance.get_attribute_values_from_tshark_messages(
                alias='tcpdump_subcase',
                filter=packet_filter,
                output_pdml_filepath="{}/converted_pcap.pdml".format(output_dir),
                element_xpath=element_xpath,
                attribute_xpath=".",
                attribute="show",
                pcap_file_path="{}/{}/tshark/{}_gnb_F1_E1_RRC.pcap".format(output_dir, test_dir, subcase)
            )
            return attribute_value
        except Exception:
            logger.console("{} is not visible in UU messages or Tcpdump Log".format(packet_filter))
            attribute_value = ["{} is not visible in UU messages or Tcpdump Log".format(packet_filter)]
            return attribute_value

    def get_CSI_ResourceList_id(self, packet_filter, alias=None, subcase=None):
        element_xpath = "//*[@name='nr-rrc.pucch_CSI_ResourceList']/*/*/*[@name='nr-rrc.pucch_Resource']"
        CSI_ResourceList_id = self.get_attribute_value_from_rrc_iterface(element_xpath, packet_filter, alias, subcase)
        return CSI_ResourceList_id[-1]

    def get_schedulingRequestResource_id(self, packet_filter, alias=None, subcase=None):
        element_xpath = "//*[@name='nr-rrc.schedulingRequestResourceToAddModList']/*/*/*[@name='nr-rrc.resource']"
        schedulingRequestResource_id = self.get_attribute_value_from_rrc_iterface(element_xpath, packet_filter, alias, subcase)
        return schedulingRequestResource_id[-1]

    def get_pucch_ResourceIds(self, packet_filter, alias=None, subcase=None):
        element_xpath = "//*[@name='nr-rrc.resourceToAddModList']/*/*/*[@name='nr-rrc.pucch_ResourceId']"
        pucch_ResourceIds = self.get_attribute_value_from_rrc_iterface(element_xpath, packet_filter, alias, subcase)
        return pucch_ResourceIds

    def get_nrofPRBs(self, packet_filter, alias=None, subcase=None):
        element_xpath = "//*[@name='nr-rrc.resourceToAddModList']/*/*/*/*/*[@name='nr-rrc.nrofPRBs']"
        nrofPRBs = self.get_attribute_value_from_rrc_iterface(element_xpath, packet_filter, alias, subcase)
        return nrofPRBs[-1]

    def extract_value_of_CSI_prb(self, prb_list, pucch_ResourceIds_list, CSI_ResourceList_id):
        for i in range(len(pucch_ResourceIds_list)):
            if int(pucch_ResourceIds_list[i]) == int(CSI_ResourceList_id):
                CSI_prb = prb_list[i]
                return CSI_prb

    def extract_value_of_SR_prb(self, prb_list, pucch_ResourceIds_list, schedulingRequestResource_id):
        for i in range(len(pucch_ResourceIds_list)):
            if int(pucch_ResourceIds_list[i]) == int(schedulingRequestResource_id):
                SR_prb = prb_list[i]
                return SR_prb

    def get_PRB_values(self, packet_filter, prb, alias=None, subcase=None):
        element_xpath = "//*[@name='nr-rrc.resourceToAddModList']/*/*/*[@name='nr-rrc.{}']".format(prb)
        PRB_values = self.get_attribute_value_from_rrc_iterface(element_xpath, packet_filter, alias, subcase)
        return PRB_values

    def _write_prb_values_to_file(self, output_dirpath=None):
        if not output_dirpath:
            output_dir = BuiltIn().get_variable_value('${OUTPUT_DIR}')
            test_dir = BuiltIn().get_variable_value('${TEST_NAME}')
        output_path = os.path.join(output_dir, test_dir, ENB_SUBDIR, 'PRB_info.txt')
        with open(output_path, 'w') as outfile:
            for key, value in startingPRB_dict.items():
                outfile.write("---------------------------------------PRB values for UE: {}---------------------------------------\n".format(key))
                outfile.write("startingPRB values for UE: {}: {}\n".format(key, value['startingPRB_ue_list_value']))
                outfile.write("secondHopPRB values for UE: {}: {}\n".format(key, secondHopPRB_dict[key]['secondHopPRB_ue_list_value']))
                outfile.write("CSI_startingPRB values for UE: {}: {}\n".format(key, value['CSI_startingPRB']))
                outfile.write("CSI_secondHopPRB values for UE: {}: {}\n".format(key, secondHopPRB_dict[key]['CSI_secondHopPRB']))
                outfile.write("SR_startingPRB values for UE: {}: {}\n".format(key, value['SR_startingPRB']))
                outfile.write("nrofPRBs value for UE: {}: {}\n".format(key, value['nrofPRBs']))
                outfile.write("SR_secondHopPRB values for UE: {}: {}\n".format(key, secondHopPRB_dict[key]['SR_secondHopPRB']))

    def get_timestamp_list_of_captured_messages(self, packet_filter, output_pdml_filepath,
                                                alias=DEFAULT_NG_XN_TSHARK_ALIAS):
        """
        :param alias:
        :param packet_filter:
        :param output_pdml_filepath:
        :return:
        """
        message_timestamps = ta5g_tshark().get_attribute_values_from_tshark_messages(
            alias=alias,
            filter=packet_filter,
            output_pdml_filepath=output_pdml_filepath,
            element_xpath='.//packet',
            attribute_xpath='.//field[@name="timestamp"]',
            attribute='show')
        time_format = "%H:%M:%S.%f"
        message_timestamps = [dt.datetime.strptime(re.search(r'\d+:\d\d:\d\d\.\d\d\d\d\d\d', single_time).group(0),
                                                   time_format) for single_time in message_timestamps]
        return message_timestamps

    def check_if_newer_message_appear(self, message_timestamp_threshold, packet_filter, pdml_filepath):
        message_timestamps = self.get_timestamp_list_of_captured_messages(packet_filter=packet_filter,
                                                                          output_pdml_filepath=pdml_filepath)
        return True in [message_timestamp > message_timestamp_threshold
                        for message_timestamp in message_timestamps]

    def establish_pdu_session(self, ue_id=1, pdu_id=1, nwslice=1, gw_id=1, pass_regexp=None, timeout=T3410,
                              check_timestamps=True):
        """
        Executes egate command ue_pdu_session_setup

        :param ue_id:
        :param pdu_id:
        :param nwslice:
        :param gw_id:
        :param pass_regexp:
        :param timeout:
        :param check_timestamps:
        """

        collecting_traffic_on_interface_started = \
            ta5g_setups_and_teardowns.ta5g_setups_and_teardowns.traffic_collection_on_interface_started()
        if collecting_traffic_on_interface_started and check_timestamps:
            built_in_instance = BuiltIn()
            pdml_filepath = "{}/tmp/{}.pdml".format(
                built_in_instance.get_variable_value(r"${OUTPUT DIR}"),
                built_in_instance.get_variable_value(r"${TEST NAME}")
            )
            time.sleep(5)
            message_timestamps = self.get_timestamp_list_of_captured_messages(packet_filter="ngap",
                                                                              output_pdml_filepath=pdml_filepath)
            last_ngap_message_timestamp = message_timestamps[-1]

        if not pass_regexp:
            pass_regexp = r'Established PDU session ID=\d+ using PDU Gateway ID=\d+'
        logger.console("Establishing PDU Session UE:{}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_pdu_session_setup ue={} pdu={} nwslice={} gw={}'.format(ue_id, pdu_id, nwslice, gw_id),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

        if collecting_traffic_on_interface_started and check_timestamps:
            packet_filter = "(ngap.PDUSessionResourceSetupListCxtRes == 1 || ngap.PDUSessionResourceSetupListSURes ==" \
                            " 1) && ngap.pDUSessionID == {}".format(pdu_id)
            ta5g_admin_operations().check_until_timeout(checking_func=self.check_if_newer_message_appear,
                                                        timeout=timeout,
                                                        message_timestamp_threshold=last_ngap_message_timestamp,
                                                        packet_filter=packet_filter, pdml_filepath=pdml_filepath)

    def establish_pdu_session_with_traffic(self, ue_id=1, pdu_id=1, nwslice=1, gw_id=1, pass_regexp=None,
                                           direction='both', timeout=T3410, throughput='10kbps', check_timestamps=True):
        """
        :param ue_id:
        :param pdu_id:
        :param nwslice:
        :param gw_id:
        :param pass_regexp:
        :param timeout:
        :param throughput:
        :param check_timestamps:
        """

        self._ute_wtssim_instance.execute_egate_command(cmd="set_pdu_param ue={} pdu={} trf_type=internal".format(ue_id, pdu_id))
        self.establish_pdu_session(ue_id, pdu_id, nwslice, gw_id, pass_regexp, timeout, check_timestamps)
        self.ta5g_throughput.start_data_traffic(ues=ue_id, direction=direction, pdu=pdu_id, throughput=throughput)

