    def ue_rrc_reconf_param(self, ue_id, **kwargs):
        """
        Command for configuring rules to specify action in RRC Connection Reconfiguration message
        :param ue_id: int: identifier of ue.
        """
        logger.console(
            "Configures rules to specify action in RRC Connection Reconfiguration messages, UE id={}".format(ue_id))
        parameters = ['reset', 'if_contains', 'nth', 'delay', 'action', 'at', 'cell', 'enb', 'ue', 'meas_id', 'crnti',
                      'cause', 'by', 'gnb', 'retries', 'meas_report_nr_event_id', 'report_nr_srsrp', 'report_nr_srsrq',
                      'report_nr_ssinr', 'nr_cgi_info_plmn', 'nr_cgi_info_tac', 'nr_cgi_info_ran', 'nr_cgi_info_ci',
                      'pci', 'report_nr_nrsrp', 'report_nr_nrsrq', 'report_nr_nsinr']
        arguments = self._verify_and_prepare_parameters(parameters, kwargs)
        self._ute_wtssim_instance.execute_egate_command(
            cmd="ue_rrc_reconf_param id={} ".format(ue_id) + arguments
        )

    def ue_nr_rrc_reconf_param(self, ue_id=1, if_contains=None, action=None, skip_processing=None, cause=None,  # noqa: C901
                               crnti=None, delay=None, timeout=10):
        """
        Executes egate command ue_nr_rrc_reconf_param
        (trigger protocol error at RRC level after pdu session establishment)

        :param ue_id:           1..25000                        Specified UE ID
        :param if_contains:     set of following, -separated
                                                   (Toggle to enable present fields in NR RRC Reconfiguration)
                                srb_to_add_mod                  SRB-ToAddModList
                                drb_to_add_mod                  DRB-ToAddModList
                                drb_to_release                  DRB-ToReleaseList
                                scell_to_add_mod                SCellToAddModList-r10
                                scell_to_relese                 SCellToReleaseList-r10
                                mobility_control_info           MobilityControlInfo
                                meas_config                     MeasConfig
                                sib1_dedicated                  SystemInfomationBlockType1Dedicated-r11
                                eventA4                         EventA4
                                nr_config                       nr-Config-r15
                                scell_to_add_mod_r13            SCellToAddModListExt-r13
                                scell_to_release_r13            SCellToReleaseListExt-r13
                                enable_256_qam_r14              enable256QAM-r14
                                nr_scg_config                   nr-SecondaryCellGroupConfig-r15
                                reconfiguration_with_sync       ReconfigurationWithSync
                                report_cgi                      ReportCGI
                                any                             any
        :param action:          Action to perform on message received, one of the following:
                                none                            Do nothing
                                drop                            Ignore message
                                reestablish                     Initiate RRC reestablishment
                                ho                              Initiate handover
                                invalid_tid                     Respond with invalid transaction id
                                s1ap_erab_setup                 Initiate S1AP E-RAB Setup
                                s1ap_erab_release               Initiate S1AP E-RAB Release
                                s1ap_erab_modify                Initiate S1AP E-RAB Modification
                                s1ap_ue_ctx_modify              Initiate S1AP UE Context Modification (reauthentication)
                                s1ap_ue_ctx_release             Initiate S1AP UE Context Release
                                measurement_send                Send measurement report
                                measurement_send_nr             Send NR measurement report
                                reestablish_after_reconf_complete
                                                                Initiate RRC reestablishment after
                                                                RRC ReconfigurationComplete
                                x2ap_sgnb_change_required       Initiate SgNB Change Required
                                no_scg_config_response_nr       Respond with RRCConnectionReconfigurationComplete
                                                                without IE 'scg-ConfigResponseNR-r15'
                                reestablish_with_timer          Initiate RRC Reestablishment
                                                                with Reestablishing State Timer
                                report_noSIB1                   Send Measurement Report with CGI-infoNR
                                                                containing the IE noSIB1
                                donot_send_NRCGI                Do not send Measurement Report with CGI_info IE
                                report_noSIB1AndnoNRCGI         Send Measurement Report with CGI-infoNR containing
                                                                neither CGI-Info nor noSIB1 IE
                                tester_filled_cgi_info          Tester specified PLMNInfo to be filled
        :param skip_processing: Toggle to enable/disable processing of NR-RRC-Reconfiguration when action is set to
                                invalid_tid or send_hex. Processing will be done if omitted
                                on|off
        :param crnti:           source                          Use source CRNTI in Reestablishment Request
                                target                          Use target CRNTI in Reestablishment Request
        :param cause:           one of the following:           Reestablishment cause (otherFailure if omitted)
                                reconfigurationFailure          Set reestablishment cause to reconfigurationFailure(0x0)
                                handoverFailure                 Set reestablishment cause to handoverFailure(0x1)
                                otherFailure                    Set reestablishment cause to otherFailure(0x2)
                                spare1                          Set reestablishment cause to spare1(0x3)
                                                                    *Note that this will change in future releases
        :param delay:           Specifies delay, after which action related to incoming RRC Reconf message is performed.
                                0..65535 + postfix (ms, s, m)
        :param timeout: timeout
        """
        not_mandatory_parameters = ''
        if if_contains:
            not_mandatory_parameters += " if_contains={}".format(if_contains)
        if action:
            not_mandatory_parameters += " action={}".format(action)
        if skip_processing:
            not_mandatory_parameters += " skip_processing={}".format(skip_processing)
        if crnti:
            not_mandatory_parameters += " crnti={}".format(crnti)
        if cause:
            not_mandatory_parameters += " cause={}".format(cause)
        if delay:
            not_mandatory_parameters += " delay={}".format(delay)
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_nr_rrc_reconf_param id={}{}'.format(ue_id, not_mandatory_parameters),
            timeout=timeout
        )

    def modify_pdu_session(
        self,
        ue_id=1,
        pdu_id=1,
        qos_to_add=None,
        qos_to_del=None,
        pass_regexp=None,
        by='amf',
        validation='on',
        timeout=10,
    ):

        """
        Executes egate command ue_pdu_session_modify

        :param ue_id: Egate's UE ID of which PDU session shall be modified.
        :param pdu_id: ID of PDU Session asocciated to UE, which needs to be modified
        :param qos_to_add: ID's of QoS flows to add into particular PDU session
        :param qos_to_del: ID's of egate defined QoS flows to delete from particular PDU session
        :param pass_regexp: Egate output which indicates that operation is a success
        :param by: Initiator of procedure. It can be either 'ue' or 'amf'
        :param validation: Specifies if AMF or UE should validate if procedure is valid
                           F.e if You want to delete nonexisting PDU session, with this turned off, AMF/UE will skip
                           validating input data, and will allow to send 'faulty' message.
        :param timeout: timeout
        """

        if not pass_regexp:
            pass_regexp = r"Pdu Session Resource Modify Response Message with RAN UE NGAP ID \d+ handled successfully"
        logger.console('Modifying PDU Session ID {} for UE ID {}'.format(pdu_id, ue_id))
        qos_string = ''
        if qos_to_add:
            qos_string += "qosflows_to_add={} ".format(qos_to_add)
        if qos_to_del:
            qos_string += "qosflows_to_del={} ".format(qos_to_del)
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_pdu_session_modify ue={} pdu={} {} by={} validation={}'.format(
                ue_id, pdu_id, qos_string, by, validation
            ),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

    def modify_multiple_pdu_sessions(
        self,
        pdu_ids_list,
        ue_id=1,
        qos_to_add=None,
        qos_to_del=None,
    ):

        """
        Executes egate command ue_pdu_session_modify for specified pdu ids list

        :param pdu_ids_list: list of pdu ids for modification
        :param ue_id: Egate's UE ID of which PDU session shall be modified.
        :param pdu_id: ID of PDU Session asocciated to UE, which needs to be modified
        :param qos_to_add: ID's of QoS flows to add into particular PDU session
        :param qos_to_del: ID's of egate defined QoS flows to delete from particular PDU session
        """

        for pdu_id in pdu_ids_list:
            self.modify_pdu_session(ue_id=ue_id, pdu_id=pdu_id, qos_to_add=qos_to_add, qos_to_del=qos_to_del)

    def modify_pdu_session_multi_pdu(self, ue_id, pdu_matrix, pass_regexp=None, validation='on', timeout=10):

        """
        Executes egate command ue_pdu_session_modify but allows to modify multiple PDU sessions used by single UE using
        single PDU_Session_Modify_Request message transfer

        :param ue_id: Egate's UE ID of which PDU session shall be modified.
        :param pdu_matrix: matrix ( list of lists ) of PDU sessions to modify with its parameters,
                                each row should contain : [PDU_ID,QoS_To_Add,QoS_To_Del].
                                If there is no Qos to add or delete, put None.
                                QoS should be string, if there is more then one to add / delete, just add those after
                                a comma.
                                Example for 3 PDUS:
                                pdu_matrix = [['1', '1,2', None], ['2', None, '2'], ['3', '1,2', '3' ]]
                                1st PDU - Add qos flows ID 1 and 2
                                2nd PDU - Remove QoS flow ID 2
                                3rd PDU - Add QoS ID 1 and 2 and remove QoS ID 3
        :param pass_regexp: Egate output which indicates that operation is a success
        :param timeout: Timeout for waiting for pass_regex string to appear/
        :param validation: Specifies if AMF or UE should validate if procedure is valid
                           F.e if You want to delete nonexisting PDU session, with this turned off, AMF/UE will skip
                           validating input data, and will allow to send 'faulty' message.
        """
        pdu_modify_string = ""
        for pdu_session_info in pdu_matrix:
            pdu_modify_string += "pdu={} ".format(pdu_session_info[0])
            if pdu_session_info[1]:
                pdu_modify_string += "qosflows_to_add={} ".format(pdu_session_info[1])
            if pdu_session_info[2]:
                pdu_modify_string += "qosflows_to_del={} ".format(pdu_session_info[2])

        if not pass_regexp:
            pass_regexp = r"Pdu Session Resource Modify Response Message with RAN UE NGAP ID \d+ handled successfully"

        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_pdu_session_modify ue={} {} by=amf validation={}'.format(ue_id, pdu_modify_string, validation),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

