    def attach_ue_to_enb(
        self,
        ue_id,
        optional_parameters='',
        cell=None,
        enb='1',
        establishment_cause=None,
        establishment_cause_nb=None,
        timeout=T3410,
        pass_regexp=None,
    ):
        """
        Executes egate command ue_attach

        :param ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param establishment_cause:
        :param establishment_cause_nb:
        :param timeout:
        :param pass_regexp:
        """
        if not pass_regexp:
            pass_regexp = r'UE{}: [=]+ UE IS ACTIVE'.format(ue_id)
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        if establishment_cause:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause={}'.format(ue_id, establishment_cause)
            )
        if establishment_cause_nb:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause_nb={}'.format(ue_id, establishment_cause_nb)
            )
        logger.console("Attaching UE {}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_attach id={} {}'.format(ue_id, optional_parameters), pass_regexp=pass_regexp, timeout=timeout
        )

    def _attach_ue_with_pathloss_and_check_regexp(
        self, ue_id, pathloss, cell=None, enb='1', timeout=45, pass_regexp=None, fail_regexp=None
    ):
        """
        :param ue_id:
        :param pathloss: RS measured path loss in dB, possible values ={28..160} (default = 60 dB)
        :param cell:
        :param enb:
        :param timeout:
        :param pass_regexp:
        :param fail_regexp:
        """
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        logger.console("Attaching UE {} with pathloss={} to cell={}".format(ue_id, pathloss, cell))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_ul_power_control id={} pathloss={}'.format(ue_id, pathloss)
        )
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} '.format(ue_id), pass_regexp=pass_regexp, fail_regexp=fail_regexp, timeout=timeout
        )

    def attach_ue_with_pathloss(self, ue_id, pathloss, cell=None, enb='1', timeout=45):
        """
        :param timeout:
        :param enb:
        :param ue_id:
        :param cell:
        :param pathloss: RS measured path loss in dB, possibles values ={28...160}
        Example of use:    ue_id=1    cell=1    pathloss=60    timeout=45
        """

        self._attach_ue_with_pathloss_and_check_regexp(
            ue_id,
            pathloss,
            cell,
            enb='1',
            timeout=timeout,
            pass_regexp='UE{}: [=]+ UE IS ACTIVE'.format(ue_id),
            fail_regexp=None,
        )

