    def attach_multiple_ues_without_confirmation(self, first_ue_id, last_ue_id, optional_parameters=''):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param optional_parameters:
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.attach_ue_without_confirmation(ue_id, optional_parameters)

    def attach_list_of_ues(self, list_of_ues, *args):
        """
        :param list_of_ues:
        """
        ues_list = list_of_ues if isinstance(list_of_ues, list) else [list_of_ues]
        for ue in args:
            ues_list.append(ue)
        for ue_id in ues_list:
            self.attach_ue(ue_id, timeout=self.T3410)

    def attach_multiple_ues(self, first_ue_id, last_ue_id, optional_parameters='', cell=None, enb='1', timeout=T3410):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param timeout:
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.attach_ue(ue_id, optional_parameters, cell, enb, timeout=timeout)

    def attach_ue_and_expect_attempts_exhaustion(self, ue_id, optional_parameters='', cell=None, enb='1', timeout=120):
        """
        :param ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param timeout:
        """
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        logger.console("Attaching UE {}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} {}'.format(ue_id, optional_parameters),
            pass_regexp='UE{}: RRC attempts exhausted'.format(ue_id),
            fail_regexp='UE{}: [=]+ UE IS ACTIVE'.format(ue_id),
            timeout=timeout,
        )

    def attach_ue_and_confirm_rejected_connection(self, ue_id, optional_parameters='', cell=None, enb='1', timeout=5):
        """
        :param ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param timeout:
        """
        logger.console("Attaching UE {}".format(ue_id))
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} {}'.format(ue_id, optional_parameters),
            pass_regexp='UE{}: RRC connection rejected.'.format(ue_id),
            timeout=timeout,
        )

    def attach_ue_and_wait_for_preprovisioned_bearers(
        self, ue_id, bearer_count, optional_parameters='', cell=None, enb=1
    ):
        """
        :param ue_id:
        :param bearer_count:
        :param optional_parameters:
        :param cell:
        :param enb:
        """
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        logger.console("Attaching UE {}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} {}'.format(ue_id, optional_parameters),
            pass_regexp='UE{}: [=]+ UE IS ACTIVE'.format(ue_id),
            timeout=self.T3410,
        )
        self._wait_until_ue_has_given_number_of_bearers(ue_id, bearer_count)

    def attach_ue_and_expect_release(
        self, ue_id, optional_parameters='', cell=None, enb='1', establishment_cause=None, establishment_cause_nb=None
    ):
        """
        :param ue_id:
        :param optional_parameters:
        :param cell:
        :param enb:
        :param establishment_cause:
        :param establishment_cause_nb:
        """
        if cell is not None:
            self.change_ue_location_without_confirmation(ue_id, enb, cell)
        if establishment_cause:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause={}'.format(ue_id, establishment_cause)
            )
        if establishment_cause_nb:
            self._ute_wtssim_instance.execute_egate_command(
                cmd='ue_param id={} establishment_cause_nb={}'.format(ue_id, establishment_cause_nb)
            )
        logger.console("Attaching UE {}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={} {}'.format(ue_id, optional_parameters),
            pass_regexp='UE{}: detached'.format(ue_id),
            fail_regexp='UE{}: [=]+ UE IS ACTIVE'.format(ue_id),
            timeout=120,
        )

    def attach_ue_with_no_response(self, ue_id):
        """
        :param ue_id:
        """
        logger.console('Attaching UE {}, no answer'.format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_register id={}'.format(ue_id),
            pass_regexp='UE{}: T300 expiration: No response to RRCSetupRequest'.format(ue_id),
        )

    def deregister_ue(self, ue_id, by='ue', ue_deregister_type='switch_off', pass_regexp=None, timeout=5):
        """
        :param ue_id:
        :param by:
        :param ue_deregister_type:
        :param pass_regexp:
        :param timeout:
        """
        if not pass_regexp:
            pass_regexp = (
                r'Received UE Context Release Complete from GNB-\d+; UE with RAN UE NGAP ID \d+, AMF UE '
                r'NGAP ID \d+ will be deallocated.'
            )
        logger.console("Deregister UE:{}".format(ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_deregister id={} by={} ue_deregister_type={}'.format(ue_id, by, ue_deregister_type),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

    def detach_ue(self, ue_id, type='ue', timeout=5):
        """
        Executes egate command ue_detach

        :param ue_id:
        :param type:
        :param timeout:
        """
        logger.console("Detaching UE {} triggered by {}".format(ue_id, type))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_detach id={} {}'.format(ue_id, type), pass_regexp='UE{}: detached'.format(ue_id), timeout=timeout
        )

    def detach_ue_and_wait_for_egate_console_output(self, ue_id, type, pass_regexp, fail_regexp, timeout=5):
        """
        :param ue_id:
        :param type:
        :param pass_regexp:
        :param fail_regexp:
        :param timeout:
        """
        logger.console(
            "Detaching UE {} triggered by {} without confirmation and waiting for egate output matching {}".format(
                ue_id, type, pass_regexp
            )
        )
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_detach id={} {}'.format(ue_id, type),
            pass_regexp=pass_regexp,
            fail_regexp=fail_regexp,
            timeout=timeout,
        )

    def detach_multiple_ues(self, first_ue_id, last_ue_id, type='ue', timeout=5):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param type:
        :param timeout:
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.detach_ue(ue_id, type, timeout)

    def detach_multiple_ues_without_confirmation(self, first_ue_id, last_ue_id, type='ue'):
        """
        :param first_ue_id:
        :param last_ue_id:
        :param type:
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.detach_ue_without_confirmation(ue_id, type)

    def detach_ue_without_confirmation(self, ue_id, type='ue'):
        """
        :param ue_id:
        :param type:
        """
        logger.console("Detaching UE {} triggered by {} without confirmation".format(ue_id, type))
        self._ute_wtssim_instance.execute_egate_command(cmd='ue_detach id={} {}'.format(ue_id, type))

    def detach_all_ues(self):
        """
        Method gets UE ids using get_ids_of_configured_ues and than detaches all of them
        """
        configured_ues_ids = self.get_ids_of_configured_ues()
        number_configured_ues = self.get_total_number_of_configured_ues()
        if len(configured_ues_ids) > 1:
            self.detach_ue_without_confirmation('{}'.format(''.join(["1-", str(number_configured_ues)])))
            self.detach_ue_without_confirmation('{}'.format(','.join(configured_ues_ids)))
        else:
            self.detach_ue_without_confirmation('{}'.format(configured_ues_ids[0]))

    def detach_ue_with_history(self, ue_id):
        """
        :param ue_id:
        """
        self.detach_ue(ue_id)
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_history_information_list id={} action=commit'.format(ue_id)
        )
        self._ute_wtssim_instance.execute_egate_command(cmd='ue_enb_param id={0} ue_history_list={0}'.format(ue_id))

