        logger.console("Performing handover to enb {} cell {} for UE {}".format(dst_enb, dst_cell, ue_id))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_ho id={} enb={} cell={}'.format(ue_id, dst_enb, dst_cell),
            pass_regexp=r'UE{0}: =* (S1 HO \(eNB .->eNB {1}\) '
            r'performed|Int..-SGW X2 Handover \(eNB . -> eNB {1}\) completed =*)'.format(ue_id, dst_enb),
            timeout=5,
        )

