    def initiate_ue_rrc_reestablishment(self, ue_id=1, timeout=10, pass_regexp=None, wait_time=5, **kwargs):
        """
        Initiates UE RRC Reestablishment procedure by executing egate command ue_rrc_reestablish with customised options

        :param ue_id: int (range 1-25000): Specified UE ID (1 if omitted)
        :param timeout: int: Timeout for the egate command processing (default is 10 seconds)
        :param pass_regexp: str: Pass regex to check in egate_console.log file. Default is None - during processing of
                                 the method, a list of commonly encountered regexes is checked: 'AMF-1: Reauthentication
                                 procedure is complete', 'UE{}: NR RRC Reestablishment sucessfully completed'.format(ue_id)
        :param wait_time: int: time (in seconds) to wait for processing of the 'ue_rrc_reestablish' command, default 5s
        :param kwargs:
               enb: int (range 1-254): eNB index for reestablishment (current if omitted)
               gnb: int (range 1-254): gNB index for reestablishment (current if omitted)
               cell: int (range 1-257): cell index for reestablishment (current if omitted)
               retries: int (range 0-1) number of reestablishment retries attempts after RACH (N/A if omitted)
               cause: str: Reestablishment cause (otherFailure if omitted), one of the following:
                           reconfigurationFailure
                           handoverFailure
                           otherFailure
                           spare1  *Note that this will change in future releases
               cause_nb: str: Reestablishment cause for NB-IoT UE (otherFailure if omitted), one of the following:
                           reconfigurationFailure
                           otherFailure
                           spare2  *Note that this will change in future releases
                           spare1  *Note that this will change in future releases
               action: str: Send unknown CRNTI or invalid short MAC-I in RRC Reestablishment Request (None if omitted),
                           one of the following:
                           invalid_short_mac_i - Send RRC Reestablishment Request with invalid short MAC-I
                           invalid_crnti - Send RRC Reestablishment Request with unknown C-RNTI

        Examples of usage:

        Initiate UE RRC Reestablishment     cause=reconfigurationFailure   pass_regexp=Reestablishment sucessfully completed
        will run egate command:
        ue_rrc_reestablish id=1 cause=reconfigurationFailure

        Initiate UE RRC Reestablishment     ue_id=10    gnb=2   cell=1
        will run egate command:
        ue_rrc_reestablish id=10 gnb=2 cell=1
        """
        logger.console(
            "Performing custom RRC Reestablishment for UE id {}".format(ue_id))
        arguments = " ".join(["{}={}".format(key, value) for key, value in kwargs.items()])
        if not pass_regexp:
            pass_regexp = ["AMF-1: Reauthentication procedure is complete",
                           "UE{}: NR RRC Reestablishment sucessfully completed".format(ue_id)]
            self._ute_wtssim_instance.execute_egate_command(
                cmd="ue_rrc_reestablish id={} ".format(ue_id) + arguments,
                timeout=timeout)
            time.sleep(wait_time)
            self._ute_wtssim_instance.execute_egate_command(
                cmd="set_log flush")
            for regex in pass_regexp:
                cmd = "grep '{}' /opt/iphy/latest/egate_console.log | wc -l".format(regex)
                occurrence = int(subprocess.check_output(cmd, shell=True))
                if occurrence >= 1:
                    logger.console('Reestablishment handled correctly: {}'.format(regex))
                    return True
            raise ExecutionFailed(message='Reestablishment not handled correctly, pass_regexp not found')
        else:
            self._ute_wtssim_instance.execute_egate_command(
                cmd="ue_rrc_reestablish id={} ".format(ue_id) + arguments,
                timeout=timeout,
                pass_regexp=pass_regexp
            )
            time.sleep(wait_time)

