    def reestablishment_in_current_cell_and_wait_for_rrc_connection_reconfiguration_complete(self, ue_id):
        """
        This method uses ute_tshark to verify rrc_connection_reconfiguration_complete during reestablishment procedure

        :param ue_id:
        """
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        ta5g_tshark_instance = ta5g_tshark()
        tshark_alias = 'reestablishment' + ta5g_file_system().get_timestamp_for_filesystem()
        tshark_filename = tshark_alias + '.pcap'
        ta5g_tshark_instance.start_tshark(log_filename=tshark_filename, eth_interface='eth4', alias=tshark_alias)
        ute_tshark_instance.start_counting_packets(
            packet_filter=ta5g_tshark_instance.RRC_CONNECTION_RECONFIGURATION_COMPLETE, alias=tshark_alias
        )
        self.reestablishment_to_current_cell(ue_id)
        ute_tshark_instance.wait_for_given_packets_number(packet_number=1, timeout=10, alias=tshark_alias)
        ute_tshark_instance.stop_counting_packets(alias=tshark_alias)
        ta5g_tshark_instance.stop_tshark(tshark_alias)

