    def get_ue_tput(self, ue_id, ue_stats_type, tput_type, optional_parameters=''):
        """
        Return min/max/current/average value of pdsch/pusch/dl_mac/ul_mac/dl_rlc/ul_rlc
        throughput for given UE.
        """
        if ue_stats_type not in ("pdsch", "pusch", "dl_mac", "ul_mac", "dl_rlc", "ul_rlc"):
            raise NotSupportedArgumentTypeError(ue_stats_type, "ue_stats_type")
        if tput_type not in ("average", "min", "max", "current"):
            raise NotSupportedArgumentTypeError(tput_type, "tput_type")

        raw_ue_stats_output = self.get_ue_stats(
            ue_id=ue_id, type=ue_stats_type, optional_parameters=optional_parameters
        )
        tput_vals_reg = re.compile(
            r"\s+(?P<current>\d+(?:\.\d)?)\D+(?P<min>\d+(?:\.\d)?)"
            r"\D+(?P<max>\d+(?:\.\d)?)\D+(?P<average>\d+(?:\.\d)?)"
        )
        re_match = tput_vals_reg.search(raw_ue_stats_output)

        return float(re_match.groupdict()[tput_type])

    def verify_if_load_is_divided_into_scells(self, ue_id, scell_no, ue_stats_type='pdsch'):
        """
        :param ue_id:
        :param scell_no:
        :param ue_stats_type: set of the following:
        dl_last_alloc - Last DL allocation
        dl_harq - DL DCIs info and HARQ errors for each HARQ process
        pdsch - PDSCH Statistics
        ul_last_alloc - Last UL allocation
        ul_harq - DCI0 info and UL HARQ errors for each HARQ process
        pusch - PDSCH Statistics
        dl_rlc - DL RLC Statistics
        ul_rlc - UL RLC Statistics
        dl_mac - DL MAC Statistics
        ul_mac - UL MAC Statistics
        sch - SCH Statistics
        """
        for cell_id in range(int(scell_no) + 1):
            throughput = self.get_ue_tput(
                ue_id, ue_stats_type, tput_type='average', optional_parameters='scell={}'.format(cell_id)
            )
            if not throughput:
                raise ExecutionFailed(
                    message="Throughput for cell {} should be greater than 0.0".format(cell_id),
                    continue_on_failure=True,
                )

    def verify_if_there_is_load_only_on_pcell(self, ue_id, scell_no, ue_stats_type='pdsch'):
        """
        :param ue_id:
        :param scell_no:
        :param ue_stats_type: check verify_if_load_is_divided_into_scells
        """
        pcell_throughput = self.get_ue_tput(ue_id, ue_stats_type, tput_type='average', optional_parameters='scell=0')
        if not pcell_throughput:
            raise ExecutionFailed(
                message="Throughput for primary cell should be greater than 0.0", continue_on_failure=True
            )
        for cell_id in range(1, int(scell_no) + 1):
            throughput = self.get_ue_tput(
                ue_id, ue_stats_type, tput_type='average', optional_parameters='scell={}'.format(cell_id)
            )
            if throughput:
                raise ExecutionFailed(
                    message="Throughput for scell {} should be 0.0".format(cell_id), continue_on_failure=True
                )

    def get_amf_and_ran_id(self, alias, output_filepath, tshark_filter=None):
        """
        Keyword for returning the current amf and ran ids
        :param alias:
        :param output_filepath:
        :return:
        """
        if not tshark_filter:
            tshark_filter = r'ngap.RAN_UE_NGAP_ID && ngap.AMF_UE_NGAP_ID'
        tshark_instance = ta5g_tshark()
        amf_id_list = tshark_instance.get_attribute_values_from_tshark_messages(
            alias=alias,
            filter=tshark_filter,
            output_pdml_filepath=output_filepath,
            element_xpath='.//packet',
            attribute_xpath='.//*[@name="ngap.AMF_UE_NGAP_ID"]',
            attribute='show',
        )
        ran_id_list = tshark_instance.get_attribute_values_from_tshark_messages(
            alias=alias,
            filter=tshark_filter,
            output_pdml_filepath=output_filepath,
            element_xpath='.//packet',
            attribute_xpath='.//*[@name="ngap.RAN_UE_NGAP_ID"]',
            attribute='show',
        )
        return [max(amf_id_list), max(ran_id_list)]

