    @staticmethod
    def _wait_until_ue_has_given_number_of_bearers(ue_id, bearer_count):
        """
        :param ue_id:
        :param bearer_count:
        """
        retry_interval = 0.3
        retries = 3
        bearer_count = int(bearer_count)
        while retries:
            time.sleep(retry_interval)
            retries -= 1
            if ta5g_bearers().get_ue_bearer_count(ue_id) == bearer_count:
                return True
            raise ExecutionFailed(
                message="Wrong number of bearers for UE {}. Expected: {}".format(ue_id, bearer_count),
                continue_on_failure=True,
            )

