    def _verify_and_prepare_parameters(self, all_parameters, passed_parameters):
        """
        Verify and return egate command's parameters with passed values in correct order
        :param all_parameters: egate command's parameters in correct order
        :param passed_parameters: dictionary of parameter:value
        :return:
        """
        for passed_parameter in passed_parameters.keys():
            if passed_parameter not in all_parameters:
                logger.warn("Wrong parameter name: {}".format(passed_parameter))

        parameters = " ".join(
            ["{}={}".format(parameter, passed_parameters[parameter]) for parameter in all_parameters if
             parameter in passed_parameters])

        return parameters

