    def ue_send_location_reporting_control(self, *args):
        """
        Command for triggering Location Reporting Control message.
        :param ue_id: Specified UE ID.
        :param event_type: Specified the event type for which the report is requested.
        :return:
        """
        timeout = 10
        pass_regexp = None
        timeout_string = "timeout="
        pass_regexp_string = "pass_regexp="
        arguments = ""
        for arg in args:
            if timeout_string in arg:
                timeout = arg.replace(timeout_string, '')
            elif pass_regexp_string in arg:
                pass_regexp = arg.replace(pass_regexp_string, '')
            else:
                arguments += arg + " "
        self._ute_wtssim_instance.execute_egate_command(
            cmd="ue_send_location_reporting_control {}".format(arguments),
            timeout=timeout,
            pass_regexp=pass_regexp)

