        """
        Command to set and display Area of Interest configuration for Location reporting procedure.
        :param object_id: Specified ID of area of interest list.
        :param plmn: PLMN ID to be used.
        :param nrci: List of NR cell identities to associate with the PLMN.
        :return:
        """
        arguments = " ".join(["{}={}".format(key, value) for key, value in kwargs.items()])
        self._ute_wtssim_instance.execute_egate_command(
            cmd="area_of_interest_configuration object_id={} plmn_cellid={} nrcellidentitylist={} ".format(object_id, plmn, nrci) + arguments)
